pub struct Solution;

impl Solution {
    pub fn solve_sudoku(board: &mut Vec<Vec<char>>) {
        let mut rows = [0u16; 9];
        let mut cols = [0u16; 9];
        let mut boxes = [0u16; 9];
        let mut empty = Vec::new();

        for r in 0..9 {
            for c in 0..9 {
                let ch = board[r][c];
                if ch != '.' {
                    let val = (ch as u8 - b'0') as usize;
                    let bit = 1u16 << val;
                    rows[r] |= bit;
                    cols[c] |= bit;
                    boxes[(r / 3) * 3 + c / 3] |= bit;
                } else {
                    empty.push((r, c));
                }
            }
        }

        fn dfs(
            idx: usize,
            empty: &[(usize, usize)],
            rows: &mut [u16; 9],
            cols: &mut [u16; 9],
            boxes: &mut [u16; 9],
            board: &mut Vec<Vec<char>>,
        ) -> bool {
            if idx == empty.len() {
                return true;
            }
            let (r, c) = empty[idx];
            let box_idx = (r / 3) * 3 + c / 3;
            let used = rows[r] | cols[c] | boxes[box_idx];

            for val in 1..=9 {
                let bit = 1u16 << val;
                if (used & bit) == 0 {
                    rows[r] |= bit;
                    cols[c] |= bit;
                    boxes[box_idx] |= bit;
                    board[r][c] = (b'0' + val as u8) as char;

                    if dfs(idx + 1, empty, rows, cols, boxes, board) {
                        return true;
                    }

                    rows[r] ^= bit;
                    cols[c] ^= bit;
                    boxes[box_idx] ^= bit;
                    board[r][c] = '.';
                }
            }
            false
        }

        dfs(0, &empty, &mut rows, &mut cols, &mut boxes, board);
    }
}

